from datetime import date
import json
import re

_DAY_RE = re.compile(r"\d{4}-\d{2}-\d{2}\Z")


def _validate_day(value):
    if not isinstance(value, str) or not _DAY_RE.fullmatch(value):
        raise ValueError("row day must be a YYYY-MM-DD string")
    try:
        date.fromisoformat(value)
    except ValueError as exc:
        raise ValueError("row day must be a valid date") from exc
    return value


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    try:
        rows = json.loads(text)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError("malformed JSON") from exc

    if not isinstance(rows, list):
        raise ValueError("input must be a JSON array")

    total_cents = 0
    first_day = None
    last_day = None

    for row in rows:
        if not isinstance(row, dict):
            raise ValueError("each row must be an object")

        tenant = row.get("tenant")
        if not isinstance(tenant, str) or tenant == "":
            raise ValueError("row tenant must be a nonempty string")

        amount_cents = row.get("amount_cents")
        if isinstance(amount_cents, bool) or not isinstance(amount_cents, int):
            raise ValueError("row amount_cents must be an integer")

        day = _validate_day(row.get("day"))

        total_cents += amount_cents
        if first_day is None or day < first_day:
            first_day = day
        if last_day is None or day > last_day:
            last_day = day

    return {
        "row_count": len(rows),
        "total_cents": total_cents,
        "first_day": first_day,
        "last_day": last_day,
    }
